declare(strict_types=1);

function process_mapping_metrics(): array
{
    $processes=process_mapping_processes();$instances=process_mapping_instances();$stepInstances=process_mapping_step_instances();$exceptions=process_mapping_exceptions();
    $active=array_values(array_filter($instances,fn($r)=>in_array($r['status'],['in_progress','blocked','overdue'],true)));
    $completed=array_values(array_filter($instances,fn($r)=>$r['status']==='completed'));
    $elapsed=array_filter(array_map('intval',array_column($completed,'cycle_seconds')));$avg=$elapsed?(int)round(array_sum($elapsed)/count($elapsed)):0;
    $overdue=count(array_filter($stepInstances,fn($r)=>in_array($r['status'],['active','pending'],true)&&!empty($r['due_at'])&&strtotime((string)$r['due_at'])<time()));
    return ['processes'=>count($processes),'published'=>count(array_filter($processes,fn($r)=>$r['status']==='published')),'active_instances'=>count($active),'completed_instances'=>count($completed),'open_exceptions'=>count(array_filter($exceptions,fn($r)=>$r['status']!=='resolved')),'overdue_steps'=>$overdue,'average_cycle_seconds'=>$avg,'touchless_percent'=>process_mapping_touchless_percent()];
}
function process_mapping_touchless_percent():float{$steps=process_mapping_steps();if(!$steps)return 0.0;$automated=count(array_filter($steps,fn($s)=>in_array($s['automation_mode'],['adapter_gated','automatic'],true)));return round(($automated/count($steps))*100,1);}
function process_mapping_process_version(array$process):?array{$id=(int)($process['active_version_id']??0);if($id>0)return process_mapping_find_version($id);$versions=process_mapping_versions((int)$process['id']);return$versions[0]??null;}
function process_mapping_map_model(int$processId,?int$instanceId=null):array
{
    $process=process_mapping_find_process($processId)??process_mapping_processes()[0]??null;if(!$process)return[];$version=process_mapping_process_version($process);if(!$version)return[];
    $lanes=process_mapping_lanes((int)$version['id']);$steps=process_mapping_steps((int)$version['id']);$transitions=process_mapping_transitions((int)$version['id']);$controls=process_mapping_controls();$integrations=process_mapping_integrations();
    $instance=$instanceId?process_mapping_find_instance($instanceId):null;if(!$instance){$matching=process_mapping_instances((int)$process['id']);$instance=$matching[0]??null;}
    $statuses=[];$stepInstances=[];$exceptions=[];if($instance){$stepInstances=process_mapping_step_instances((int)$instance['id']);foreach($stepInstances as$si)$statuses[(int)$si['step_id']]=$si['status'];$exceptions=process_mapping_exceptions((int)$instance['id']);}
    foreach($steps as&$step){$step['runtime_status']=$statuses[(int)$step['id']]??'not_started';$step['controls']=array_values(array_filter($controls,fn($c)=>(int)$c['step_id']===(int)$step['id']));$step['integrations']=array_values(array_filter($integrations,fn($c)=>(int)$c['step_id']===(int)$step['id']));}unset($step);
