function process_mapping_analytics():array
{
    $instances=process_mapping_instances();$steps=process_mapping_step_instances();$processNames=[];foreach(process_mapping_processes()as$p)$processNames[(int)$p['id']]=$p['process_name'];$byProcess=[];foreach($instances as$i){$name=$processNames[(int)$i['process_id']]??'Unknown';$byProcess[$name]['volume']=($byProcess[$name]['volume']??0)+1;$byProcess[$name]['completed']=($byProcess[$name]['completed']??0)+($i['status']==='completed'?1:0);$byProcess[$name]['cycle_total']=($byProcess[$name]['cycle_total']??0)+(int)$i['cycle_seconds'];}
    foreach($byProcess as&$row){$row['average_cycle_seconds']=$row['completed']?intdiv($row['cycle_total'],$row['completed']):0;$row['completion_percent']=round(($row['completed']/$row['volume'])*100,1);}unset($row);
    $bottlenecks=[];foreach($steps as$si){$step=process_mapping_find_step((int)$si['step_id']);if(!$step)continue;$name=$step['step_name'];$bottlenecks[$name]['elapsed']=($bottlenecks[$name]['elapsed']??0)+(int)$si['elapsed_seconds'];$bottlenecks[$name]['count']=($bottlenecks[$name]['count']??0)+1;$bottlenecks[$name]['exceptions']=($bottlenecks[$name]['exceptions']??0)+($si['status']==='exception'?1:0);}foreach($bottlenecks as&$b)$b['average_seconds']=$b['count']?intdiv($b['elapsed'],$b['count']):0;unset($b);uasort($bottlenecks,fn($a,$b)=>$b['average_seconds']<=>$a['average_seconds']);return ['by_process'=>$byProcess,'bottlenecks'=>$bottlenecks];
}
